"""Every environment variable this project reads is in its ``env.complete``.

The project's code (every ``.py`` file outside ``tests/``) and its shipped configs (the YAML under ``config/``,
``examples/`` and ``graphs/``, their comments left out) are read for the variables they use; each must have a
``# NAME=VALUE  description`` line in ``env.complete``, or a ``# not for .env: NAME — reason`` line when nobody sets
it in ``.env``. ``env.example``, when the project has one, holds the variables a person normally sets: each is one of
``env.complete``'s. Every line of both files is a comment or blank, so a copy of either to ``.env`` sets nothing. A
name built at run time is not seen: list it by hand.
"""

import re
from pathlib import Path
from typing import Dict, List, Set, Tuple

PROJECT = Path(__file__).resolve().parent.parent
ENV_COMPLETE = PROJECT / "env.complete"
ENV_EXAMPLE = PROJECT / "env.example"

#: The shell's and the operating system's own: read everywhere, set by no ``.env``.
EVERYWHERE = frozenset({"PATH", "HOME", "SHELL", "TERM", "USER", "LANG", "TMPDIR", "PWD", "COLUMNS", "LINES"})

#: Folders that are no part of the project's code: tests, environments, build and run output.
SKIP = frozenset(
    {"tests", ".git", ".venv", "venv", "build", "dist", "runs", "node_modules", "__pycache__", "wheels", "logs"}
)
CONFIG_FOLDERS = ("config", "examples", "graphs")

_NAME = r"([A-Z_][A-Z0-9_]*)"
CODE = tuple(
    re.compile(pattern)
    for pattern in (
        r"""environ\.get\(\s*["']""" + _NAME + r"""["']""",
        r"""environ\[\s*["']""" + _NAME + r"""["']\s*\]""",
        r"""environ\.setdefault\(\s*["']""" + _NAME + r"""["']""",
        r"""getenv\(\s*["']""" + _NAME + r"""["']""",
    )
)
CONFIG = (
    re.compile(r"\$\{env:" + _NAME),
    re.compile(r"\$\{" + _NAME + r"\}"),
    re.compile(r"(?<![\w$])\$" + _NAME + r"\b"),
)

#: A YAML comment — prose like "`$VAR` is expanded", or a block left commented out — reads nothing.
_YAML_COMMENT = re.compile(r"(?:^|\s)#.*$")

_ENTRY = re.compile(r"^#\s*" + _NAME + r"=")
_NOT_FOR_ENV = re.compile(r"^#\s*not for \.env:\s*(.+?)\s+(?:—|--|-)\s+")


def _skipped(path: Path) -> bool:
    parts = path.relative_to(PROJECT).parts[:-1]
    return any(part in SKIP or part.startswith(".") or part.endswith(".egg-info") for part in parts)


def _variables(path: Path) -> Set[str]:
    return {entry.group(1) for entry in map(_ENTRY.match, path.read_text().splitlines()) if entry}


def _listed() -> Set[str]:
    names = _variables(ENV_COMPLETE)
    for line in ENV_COMPLETE.read_text().splitlines():
        plumbing = _NOT_FOR_ENV.match(line)
        if plumbing:
            names.update(plumbing.group(1).replace(",", " ").split())
    return names


def _setting_lines(path: Path) -> List[str]:
    return [
        f"{path.name}:{number} sets a variable: {line}"
        for number, line in enumerate(path.read_text().splitlines(), start=1)
        if line.strip() and not line.startswith("#")
    ]


def _read() -> Dict[str, List[str]]:
    """Each variable the code and the shipped configs read, with the ``file:line`` places that read it."""
    found: Dict[str, List[str]] = {}
    files: List[Tuple[Path, Tuple[re.Pattern, ...]]] = [
        (path, CODE) for path in sorted(PROJECT.rglob("*.py")) if not _skipped(path)
    ]
    for folder in CONFIG_FOLDERS:
        for suffix in ("*.yaml", "*.yml"):
            files += [(path, CONFIG) for path in sorted((PROJECT / folder).rglob(suffix)) if not _skipped(path)]
    for path, patterns in files:
        for number, line in enumerate(path.read_text(errors="ignore").splitlines(), start=1):
            if patterns is CONFIG:
                line = _YAML_COMMENT.sub("", line)
            for pattern in patterns:
                for name in pattern.findall(line):
                    found.setdefault(name, []).append(f"{path.relative_to(PROJECT)}:{number}")
    return found


def test_every_line_of_both_files_is_a_comment() -> None:
    assert ENV_COMPLETE.is_file(), f"{ENV_COMPLETE} is missing: list the variables this project reads in it"
    setting = _setting_lines(ENV_COMPLETE) + (_setting_lines(ENV_EXAMPLE) if ENV_EXAMPLE.is_file() else [])
    assert not setting, (
        "\n".join(setting) + "\nComment it out (# NAME=VALUE  description): a copy to .env sets nothing."
    )


def test_every_variable_the_code_reads_is_in_env_complete() -> None:
    listed = _listed() | EVERYWHERE
    unlisted = {name: places for name, places in _read().items() if name not in listed}
    report = [f"  {name}  ({', '.join(places[:3])})" for name, places in sorted(unlisted.items())]
    assert not unlisted, (
        "env.complete does not list these variables the project reads:\n"
        + "\n".join(report)
        + "\nAdd a line for each: `# NAME=VALUE  description`, or `# not for .env: NAME — reason` when nobody sets it."
    )


def test_env_example_holds_only_variables_of_env_complete() -> None:
    if not ENV_EXAMPLE.is_file():
        return  # the project lists no variable a person normally sets
    extra = sorted(_variables(ENV_EXAMPLE) - _variables(ENV_COMPLETE))
    assert not extra, f"env.example lists variables env.complete does not: {', '.join(extra)} — add them there too."
